var E = {
    linear:function(t){return t;},
    inQuad:function(t){return t*t;},
    outQuad:function(t){return t*(2-t);},
    inCubic:function(t){return t*t*t;},
    outCubic:function(t){return (--t)*t*t+1;},
    inOutCubic:function(t){return t<0.5?4*t*t*t:(t-1)*(2*t-2)*(2*t-2)+1;},
    outBack:function(t){var s=1.70158;return 1+(--t)*t*((s+1)*t+s);},
    inBack:function(t){var s=1.70158;return t*t*((s+1)*t-s);},
    outElastic:function(t){if(t===0||t===1)return t;var p=0.35;return Math.pow(2,-10*t)*Math.sin((t-p/4)*(2*Math.PI)/p)+1;},
    outBounce:function(t){var n=7.5625,d=2.75;if(t<1/d){return n*t*t;}else if(t<2/d){t-=1.5/d;return n*t*t+0.75;}else if(t<2.5/d){t-=2.25/d;return n*t*t+0.9375;}else{t-=2.625/d;return n*t*t+0.984375;}}
};
function clamp01(x){return x<0?0:(x>1?1:x);}

function animate(env,el,p){
    el.transform.location.x += Math.sin(env.absTime*p.speed*12.0)*p.mag*0.3;
    return el;
}
